/* alu.c - SIM56000.EXE v6.3 (CLAS56), ALU of the core simulator and the peripheral lookup helpers (module alu).
 * The ALU works on the core register file `alu_core`; the original addresses it by byte offset (+0x45c/+0x460/+0x464
 * operand 1 ext:hi:lo... see re/notes/SIM56000/devinit_asm.md), here it is an array of 32-bit words: W(offset).
 * Most functions are generated by re/scripts/g2c_alu.py from the Ghidra output.  Words hold 32-bit values in an
 * unsigned long; SI() reads one as a signed int, ST() truncates a result to 32 bits. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "sim56000.h"
#include "simdata.h"
