unsigned long alu_ccr;              /* 0x4dc13c CCR collected by the operation */
long alu_flag;                      /* 0x4dc140 0 = the handler took care of the CCR write back */

#define W(off) (alu_core[(off) >> 2])
#define ST(x) ((unsigned long)(x) & 0xffffffffUL)
#define SI(x) ((long)(((unsigned long)(x) & 0xffffffffUL) ^ 0x80000000UL) - 0x80000000L)
#define SC(x) ((long)(((unsigned long)(x) & 0xffUL) ^ 0x80UL) - 0x80L)

