void alu_h_432a70(void);

/* opcode validity: 0 = invalid, 1 = valid, 2 = valid without further checks */
long insn_validate(unsigned long opw, unsigned long devflags)
{
    long r;

    r = ((long (*)(unsigned long))insn_valid_handlers[opclass_lookup(opw, devflags)])(opw);
    if (r == 2)
        return 2;
    return r == 0;
}

/* sign extension word of the 24 bit word in core word src -> core word dst */
void sign_ext_word(long src, long dst)
{
    if (0x7fffffL < SI(alu_core[src]))
        alu_core[dst] = 0xff;
    else
        alu_core[dst] = 0;
}

void alu_load_src(long mode)
{
    unsigned long src;

    if (SI(W(0x1c8)) == 300 || SI(W(0x1c8)) == 2) {
        core_read_copy(1, 0x11a);
        core_read_copy(2, 0x11b);
        src = 3;
    } else {
        core_read_copy(5, 0x11a);
        core_read_copy(6, 0x11b);
        src = 7;
    }
    core_read_copy(src, 0x11c);
    if (mode == 0)
        core_read_copy(W(0x1c0), 0x117);
    else
        W(0x45c) = ST(d_4c4e50[(SI(W(0x1c0)) >> 8) & 0x1f]);
    core_read_copy(W(0x1c4), 0x118);
}

/* one bit shift of the accumulator (ASL/ASR family; called with the core directly) */
void alu_shift1(void *core)
{
    unsigned long uVar1, uVar2;
    long src;

    alu_core = (unsigned long *)core;
    alu_ccr = W(0x9c);
    uVar2 = (unsigned long)((SI(W(0x184)) >> 8) & 7);
    src = (uVar2 > 3) + 0x4d;
    W(0x1c8) = ST(((W(0x184) & 8) | 0x960) >> 3);
    uVar1 = alu_ccr;
    alu_ccr = ST(alu_ccr & 0xffffffc1UL);
    alu_load_acc();
    if ((uVar1 & 0x20) == 0) {
        if ((uVar1 & 0x10) == 0 || (uVar1 & 4) != 0) {
            W(0x474) = W(0x468);
            W(0x478) = W(0x46c);
            W(0x47c) = W(0x470);
        } else {
            W(0x474) = ST(SI(W(0x468)) << 1);
            W(0x478) = ST(SI(W(0x46c)) << 1);
            W(0x47c) = ST(SI(W(0x470)) << 1);
            alu_norm_res();
            alu_core[src] = ST(SI(alu_core[src]) - 1UL) & 0xffff;
            core_copy_reg((long)uVar2 + 0x1e, src);
            uVar1 = W(0x47c) & 0x180;
            if (uVar1 == 0x100 || uVar1 == 0x80)
                alu_ccr = ST(alu_ccr | 2);
        }
    } else {
        W(0x47c) = ST(SI(W(0x470)) / 2);
        if ((W(0x470) & 0x80) != 0)
            W(0x47c) = ST(W(0x47c) | 0x80);
        uVar1 = W(0x46c);
        if ((W(0x470) & 1) == 1)
            uVar1 |= 0x1000000UL;
        W(0x478) = ST(SI(uVar1) / 2);
        uVar1 = W(0x468);
        if ((W(0x46c) & 1) == 1)
            uVar1 |= 0x1000000UL;
        W(0x474) = ST(SI(uVar1) / 2);
        alu_core[src] = ST(SI(alu_core[src]) + 1UL) & 0xffff;
        core_copy_reg((long)uVar2 + 0x1e, src);
    }
    W(0x47c) = W(0x47c) & 0xff;
    W(0x480) = W(0x474);
    W(0x484) = W(0x478);
    W(0x488) = W(0x47c);
    alu_set_ccr();
    alu_store_ext();
}

/* run the ALU operation of the instruction: alu_handlers[core word 0x1b8] */
void alu_execute(void *core)
{
    alu_core = (unsigned long *)core;
    alu_ccr = W(0x9c);
    alu_flag = 1;
    ((void (*)(void))((simfn *)&alu_handlers[0].w1)[SI(W(0x1b8)) - 1])();
    if (SI(W(0x1bc)) != 1 && alu_flag != 0) {
        W(0x9c) = alu_ccr;
        core_touch_reg(0x27);
    }
}

/* ALU alu_handlers[0x18-word] table entry i of the decode tables (the words after the handler functions) */
static long alu_tab(long i)
{
    if (i < 24)
        return ((long *)alu_handlers)[40 + i];
    return d_4c4fb0[i - 24];
}

/* ALU decode: opcode word -> {handler index, 1, operand id, operand 2 id, destination accumulator, flag} */
