/* ---- peripheral helpers ---- */
void periph_reset(void)
{
    long i, j, n;
    struct periph_desc *pd;
    unsigned long *fl;

    cur_dev->flags = 0;
    cur_sim->var24 = 0;
    n = cur_dtype->n_map;
    for (i = 0; i < n; i++) {
        cur_sim->rstat[i].rd.total = 0;
        cur_sim->rstat[i].wr.total = 0;
    }
    n = cur_dtype->n_periph;
    for (i = 0; i < n; i++) {
        pd = &cur_dtype->periph[i];
        fl = cur_sim->regflags[i].flags;
        for (j = 0; j < pd->def->nreg; j++)
            fl[j] &= ~0x000f0000UL;
    }
}

long periph_call(long devidx, long periph, long a, long b)
{
    cur_dev = dev_tab[devidx];
    cur_dtype = chiptype_tab[cur_dev->type];
    ((void (*)(long, long, long))cur_dtype->periph[periph].def->peek)(periph, a, b);
    return 1;
}

/* find a peripheral register by name: exact match, else "<name><group letter>" where the last character selects
 * the group (its `enable` string starts with that letter) */
long periph_find_reg(long devidx, char *name, long *periph, long *reg)
{
    long i, j, n, len;
    struct periph_desc *pd;
    struct group_def *g;
    char last;

    cur_dev = dev_tab[devidx];
    cur_dtype = chiptype_tab[cur_dev->type];
    n = cur_dtype->n_periph;
    for (i = 0; i < n; i++) {
        pd = &cur_dtype->periph[i];
        if (*(char *)pd->enable == '\0') {
            g = pd->def;
            for (j = 0; j < g->nreg; j++) {
                if (str_icmp((char *)g->regs[j].name, name) == 0) {
                    *periph = i;
                    *reg = j;
                    return 1;
                }
            }
        }
    }
    len = (long)strlen(name) - 1;
    last = name[len];
    for (i = 0; i < n; i++) {
        pd = &cur_dtype->periph[i];
        if (last == *(char *)pd->enable) {
            g = pd->def;
            for (j = 0; j < g->nreg; j++) {
                if ((long)strlen(g->regs[j].name) == len && str_nicmp((char *)g->regs[j].name, name, len) == 0) {
                    *periph = i;
                    *reg = j;
                    return 1;
                }
            }
        }
    }
    return 0;
}

